FUNCTION_BLOCK FB_WeightControl
VAR_INPUT
    Enable : BOOL;
    AvgWeight_mg : REAL;
    Target_mg : REAL;
    Kp : REAL := 0.002;
    Ki : REAL := 0.0005;
    CycleS : REAL := 1.0;
    MaxCorr_mm : REAL := 1.0;
END_VAR
VAR_OUTPUT
    Correction_mm : REAL;
    AtLimit : BOOL;
END_VAR
VAR
    Error : REAL;
    Integral : REAL;
END_VAR

IF NOT Enable THEN
    Integral := 0.0;
    Correction_mm := 0.0;
    AtLimit := FALSE;
    RETURN;
END_IF;

Error := Target_mg - AvgWeight_mg;
Integral := Integral + Error * Ki * CycleS;

// anti wind-up: stop integrating at the limit
Integral := LIMIT(-MaxCorr_mm, Integral, MaxCorr_mm);
Correction_mm := LIMIT(-MaxCorr_mm, Kp * Error + Integral, MaxCorr_mm);
AtLimit := ABS(Correction_mm) >= MaxCorr_mm;
END_FUNCTION_BLOCK
